def choose_language_keyboard():
    return InlineKeyboardMarkup([
        [InlineKeyboardButton("🇰🇿 Қазақша", callback_data="lang:kk")],
        [InlineKeyboardButton("🇷🇺 Русский", callback_data="lang:ru")],
    ])


def menu_keyboard(lang):
    data = DATA[lang]
    rows = [[InlineKeyboardButton(info["label"], callback_data=f"section:{lang}:{key}")]
            for key, info in data["sections"].items()]
    rows.append([InlineKeyboardButton(data["change"], callback_data="language")])
    return InlineKeyboardMarkup(rows)


def section_keyboard(lang, section):
    data = DATA[lang]
    if section == "staff":
        # Telegram URL-кнопки поддерживают HTTPS, но не универсальные mailto-ссылки.
        # Поэтому почтовый адрес показываем отдельным сообщением для копирования.
        whatsapp = "https://wa.me/77052921940"
        if lang == "ru":
            rows = [
                [InlineKeyboardButton("✉️ Служебная почта", callback_data="staff_email:ru")],
                [InlineKeyboardButton("🟢 Открыть WhatsApp", url=whatsapp)],
            ]
        else:
            rows = [
                [InlineKeyboardButton("✉️ Қызметтік пошта", callback_data="staff_email:kk")],
                [InlineKeyboardButton("🟢 WhatsApp ашу", url=whatsapp)],
            ]
        rows.append([InlineKeyboardButton(data["back"], callback_data=f"menu:{lang}")])
        rows.append([InlineKeyboardButton(data["change"], callback_data="language")])
        return InlineKeyboardMarkup(rows)
    rows = [[InlineKeyboardButton(label, callback_data=f"detail:{lang}:{section}:{key}")]
            for key, label, _ in data["sections"][section]["items"]]
    rows.append([InlineKeyboardButton(data["back"], callback_data=f"menu:{lang}")])
    rows.append([InlineKeyboardButton(data["change"], callback_data="language")])
    return InlineKeyboardMarkup(rows)


def detail_keyboard(lang, section, item_key):
    rows = []
    if (lang, section, item_key) in MORE:
        title = "📖 Подробнее" if lang == "ru" else "📖 Толығырақ"
        rows.append([InlineKeyboardButton(title, callback_data=f"more:{lang}:{section}:{item_key}")])
    rows.extend([
        [InlineKeyboardButton(DATA[lang]["up"], callback_data=f"section:{lang}:{section}")],
        [InlineKeyboardButton(DATA[lang]["back"], callback_data=f"menu:{lang}")],
    ])
    return InlineKeyboardMarkup(rows)


async def start(update: Update, context: ContextTypes.DEFAULT_TYPE):
    await update.effective_message.reply_text(
        "🛡️ Территория безопасности | СКО\n"
        "🛡️ Қауіпсіздік аумағы | СҚО\n\n"
        "Тестовая версия / Сынақ нұсқасы\n\n"
        "Выберите язык / Тілді таңдаңыз:",
        reply_markup=choose_language_keyboard(),
    )


async def on_button(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()
    value = query.data or ""
    if value == "language":
        await query.edit_message_text("Выберите язык / Тілді таңдаңыз:", reply_markup=choose_language_keyboard())
        return
    parts = value.split(":")
    if len(parts) == 2 and parts[0] == "staff_email" and parts[1] in DATA:
        lang = parts[1]
        msg = (
            "✉️ НАПИСАТЬ НА СЛУЖЕБНУЮ ПОЧТУ\n\n"
            "Адрес: m.vilkova@mvd.gov.kz\n\n"
            "Скопируйте адрес, откройте почтовое приложение, составьте письмо и "
            "самостоятельно нажмите «Отправить». Бот не отправляет письма.\n\n"
            "⚠️ Это не экстренная линия и не автоматическая регистрация обращения. "
            "При опасности — 102 или 112."
            if lang == "ru" else
            "✉️ ҚЫЗМЕТТІК ПОШТАҒА ЖАЗУ\n\n"
            "Мекенжай: m.vilkova@mvd.gov.kz\n\n"
            "Мекенжайды көшіріп, пошта қолданбасында хат жазыңыз және "
            "«Жіберу» батырмасын өзіңіз басыңыз. Бот хат жібермейді.\n\n"
            "⚠️ Бұл шұғыл байланыс арнасы емес және өтініш автоматты түрде тіркелмейді. "
            "Қауіп төнсе — 102 немесе 112."
        )
        await query.edit_message_text(msg, reply_markup=InlineKeyboardMarkup([
            [InlineKeyboardButton(DATA[lang]["up"], callback_data=f"section:{lang}:staff")],
            [InlineKeyboardButton(DATA[lang]["back"], callback_data=f"menu:{lang}")],
        ]))
        return
    if len(parts) == 2 and parts[0] in ("lang", "menu") and parts[1] in DATA:
        lang = parts[1]
        await query.edit_message_text(DATA[lang]["menu"], reply_markup=menu_keyboard(lang))
        return
    if len(parts) == 3 and parts[0] == "section":
        _, lang, section = parts
        if lang in DATA and section in DATA[lang]["sections"]:
            await query.edit_message_text(
                DATA[lang]["sections"][section]["intro"],
                reply_markup=section_keyboard(lang, section),
            )
        return
    if len(parts) == 4 and parts[0] == "more":
        _, lang, section, item_key = parts
        content = MORE.get((lang, section, item_key))
        if content:
            await query.edit_message_text(content, reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton(DATA[lang]["up"], callback_data=f"section:{lang}:{section}")],
                [InlineKeyboardButton(DATA[lang]["back"], callback_data=f"menu:{lang}")],
            ]))
        return
    if len(parts) == 4 and parts[0] == "detail":
        _, lang, section, item_key = parts
        if lang in DATA and section in DATA[lang]["sections"]:
            for key, _, content in DATA[lang]["sections"][section]["items"]:
                if key == item_key:
                    await query.edit_message_text(content, reply_markup=detail_keyboard(lang, section, item_key))
                    break


def main():
    token = os.environ.get("BOT_TOKEN", "").strip()
    if not token:
        raise SystemExit("Не задан BOT_TOKEN. Добавьте токен бота в Variables на Railway.")
    app = Application.builder().token(token).build()
    app.add_handler(CommandHandler(["start", "language", "help", "rights", "protection", "centers", "contacts"], start))
    app.add_handler(CallbackQueryHandler(on_button))
    print("Бот запускается: polling.", flush=True)
    app.run_polling(drop_pending_updates=True)


if __name__ == "__main__":
    main()
